INSERT INTO public.scenarios (language_id, title, description, context, difficulty_level, category, estimated_minutes, main_objective, assistant_role, user_role, initial_assistant_message, goals, useful_phrases, is_custom, is_active, created_at)
VALUES
  (1, 'First Greetings', 'Say hello and meet someone new.', 'You meet a friendly person. Use one word to say hello.', 'PRE-A1', 'daily', 1, 'Say hello and greet someone with simple words.', 'Friendly Stranger', 'New Speaker', 'Hello!', '[{"id":"g1","text":"Say hello","keywords":["hello","hi"],"examplePhrase":"Hello"},{"id":"g2","text":"Say your name","keywords":["name"],"examplePhrase":"My name is..."},{"id":"g3","text":"Say nice to meet you","keywords":["meet"],"examplePhrase":"Nice to meet you"}]', '[{"id":"p1","phrase":"Hello!","translation":"¡Hola!"},{"id":"p2","phrase":"My name is...","translation":"Mi nombre es..."},{"id":"p3","phrase":"Nice to meet you.","translation":"Encantado de conocerte."}]', true, true, now()),
  (1, 'Introducing Your Name', 'Say your name and ask someone their name.', 'A new classmate wants to know your name.', 'PRE-A1', 'daily', 1, 'Say your name and ask for another name.', 'Classmate', 'Student', 'My name is Anna. What is your name?', '[{"id":"g1","text":"Say your name","keywords":["name"],"examplePhrase":"My name is..."},{"id":"g2","text":"Say your age","keywords":["age","years","old"],"examplePhrase":"I am ten"},{"id":"g3","text":"Say where you are from","keywords":["from"],"examplePhrase":"I am from Mexico"}]', '[{"id":"p1","phrase":"My name is...","translation":"Mi nombre es..."},{"id":"p2","phrase":"I am from...","translation":"Soy de..."},{"id":"p3","phrase":"What is your name?","translation":"¿Cómo te llamas?"}]', true, true, now()),
  (1, 'Saying Yes and No', 'Answer simple questions with yes or no.', 'A friend asks you easy questions.', 'PRE-A1', 'daily', 1, 'Answer with one word: yes or no.', 'Friend', 'New Speaker', 'Do you like coffee? Yes or no?', '[{"id":"g1","text":"Say yes","keywords":["yes"],"examplePhrase":"Yes"},{"id":"g2","text":"Say no","keywords":["no"],"examplePhrase":"No"},{"id":"g3","text":"Say please","keywords":["please"],"examplePhrase":"Yes, please"}]', '[{"id":"p1","phrase":"Yes","translation":"Sí"},{"id":"p2","phrase":"No","translation":"No"},{"id":"p3","phrase":"Yes, please.","translation":"Sí, por favor."}]', true, true, now()),
  (1, 'Please and Thank You', 'Use please and thank you with simple words.', 'Someone gives you a gift or a drink.', 'PRE-A1', 'daily', 1, 'Use please and thank you politely.', 'Friend', 'New Speaker', 'Here is a drink for you.', '[{"id":"g1","text":"Say thank you","keywords":["thank","thanks"],"examplePhrase":"Thank you"},{"id":"g2","text":"Say please","keywords":["please"],"examplePhrase":"Please"},{"id":"g3","text":"Say you are welcome","keywords":["welcome"],"examplePhrase":"You are welcome"}]', '[{"id":"p1","phrase":"Thank you.","translation":"Gracias."},{"id":"p2","phrase":"Please.","translation":"Por favor."},{"id":"p3","phrase":"You are welcome.","translation":"De nada."}]', true, true, now()),
  (1, 'Numbers 1 to 5', 'Count and say numbers from one to five.', 'You count things in a shop.', 'PRE-A1', 'daily', 1, 'Say numbers one to five.', 'Shop Clerk', 'Customer', 'How many apples? One, two, three...', '[{"id":"g1","text":"Say one","keywords":["one"],"examplePhrase":"One"},{"id":"g2","text":"Say two","keywords":["two"],"examplePhrase":"Two"},{"id":"g3","text":"Say three, four, five","keywords":["three","four","five"],"examplePhrase":"Three"}]', '[{"id":"p1","phrase":"One, two, three","translation":"Uno, dos, tres"},{"id":"p2","phrase":"Four, five","translation":"Cuatro, cinco"},{"id":"p3","phrase":"How many?","translation":"¿Cuántos?"}]', true, true, now()),
  (1, 'Numbers 6 to 10', 'Count and say numbers from six to ten.', 'You count your fingers and coins.', 'PRE-A1', 'daily', 1, 'Say numbers six to ten.', 'Friend', 'New Speaker', 'Now let us count more. Six, seven, eight...', '[{"id":"g1","text":"Say six","keywords":["six"],"examplePhrase":"Six"},{"id":"g2","text":"Say seven","keywords":["seven"],"examplePhrase":"Seven"},{"id":"g3","text":"Say eight, nine, ten","keywords":["eight","nine","ten"],"examplePhrase":"Eight"}]', '[{"id":"p1","phrase":"Six, seven, eight","translation":"Seis, siete, ocho"},{"id":"p2","phrase":"Nine, ten","translation":"Nueve, diez"},{"id":"p3","phrase":"I have ten fingers.","translation":"Tengo diez dedos."}]', true, true, now()),
  (1, 'Basic Colors', 'Say the names of simple colors.', 'You look at colored objects together.', 'PRE-A1', 'daily', 1, 'Say red, blue and yellow.', 'Friend', 'New Speaker', 'Look! What color is this?', '[{"id":"g1","text":"Say red","keywords":["red"],"examplePhrase":"Red"},{"id":"g2","text":"Say blue","keywords":["blue"],"examplePhrase":"Blue"},{"id":"g3","text":"Say yellow or green","keywords":["yellow","green"],"examplePhrase":"Green"}]', '[{"id":"p1","phrase":"It is red.","translation":"Es rojo."},{"id":"p2","phrase":"It is blue.","translation":"Es azul."},{"id":"p3","phrase":"I like green.","translation":"Me gusta el verde."}]', true, true, now()),
  (1, 'Good Morning and Good Night', 'Say good morning and good night.', 'You meet someone in the morning and at night.', 'PRE-A1', 'daily', 1, 'Greet people at different times of the day.', 'Neighbor', 'New Speaker', 'Good morning!', '[{"id":"g1","text":"Say good morning","keywords":["morning"],"examplePhrase":"Good morning"},{"id":"g2","text":"Say good afternoon","keywords":["afternoon"],"examplePhrase":"Good afternoon"},{"id":"g3","text":"Say good night","keywords":["night"],"examplePhrase":"Good night"}]', '[{"id":"p1","phrase":"Good morning.","translation":"Buenos días."},{"id":"p2","phrase":"Good afternoon.","translation":"Buenas tardes."},{"id":"p3","phrase":"Good night.","translation":"Buenas noches."}]', true, true, now()),
  (1, 'How Are You?', 'Ask and answer about feelings with one word.', 'A friend asks how you are feeling today.', 'PRE-A1', 'daily', 1, 'Say how you feel with simple words.', 'Friend', 'New Speaker', 'Hello! How are you?', '[{"id":"g1","text":"Say you are fine","keywords":["fine","good","ok"],"examplePhrase":"I am fine"},{"id":"g2","text":"Say you are tired","keywords":["tired"],"examplePhrase":"Tired"},{"id":"g3","text":"Ask how they are","keywords":["you"],"examplePhrase":"And you?"}]', '[{"id":"p1","phrase":"I am fine.","translation":"Estoy bien."},{"id":"p2","phrase":"I am tired.","translation":"Estoy cansado."},{"id":"p3","phrase":"How are you?","translation":"¿Cómo estás?"}]', true, true, now()),
  (1, 'Saying Goodbye', 'Say goodbye and see you later.', 'You finish talking and leave.', 'PRE-A1', 'daily', 1, 'Say goodbye with simple words.', 'Friend', 'New Speaker', 'It was nice to talk. Bye!', '[{"id":"g1","text":"Say goodbye","keywords":["bye","goodbye"],"examplePhrase":"Goodbye"},{"id":"g2","text":"Say see you later","keywords":["later"],"examplePhrase":"See you later"},{"id":"g3","text":"Say have a good day","keywords":["day"],"examplePhrase":"Have a good day"}]', '[{"id":"p1","phrase":"Goodbye!","translation":"¡Adiós!"},{"id":"p2","phrase":"See you later.","translation":"Hasta luego."},{"id":"p3","phrase":"Have a good day.","translation":"Que tengas un buen día."}]', true, true, now()),
  (1, 'My Family', 'Say words for family members.', 'You show a photo of your family.', 'PRE-A1', 'daily', 1, 'Say mother, father, brother and sister.', 'Friend', 'New Speaker', 'Is this your family?', '[{"id":"g1","text":"Say mother","keywords":["mother","mom","mum"],"examplePhrase":"Mother"},{"id":"g2","text":"Say father","keywords":["father","dad"],"examplePhrase":"Father"},{"id":"g3","text":"Say brother or sister","keywords":["brother","sister"],"examplePhrase":"Brother"}]', '[{"id":"p1","phrase":"This is my mother.","translation":"Esta es mi madre."},{"id":"p2","phrase":"This is my father.","translation":"Este es mi padre."},{"id":"p3","phrase":"I have one sister.","translation":"Tengo una hermana."}]', true, true, now()),
  (1, 'Body Words', 'Say simple words for the body.', 'You point to parts of the body.', 'PRE-A1', 'daily', 1, 'Say head, hand and eyes.', 'Teacher', 'Student', 'Touch your head!', '[{"id":"g1","text":"Say head","keywords":["head"],"examplePhrase":"Head"},{"id":"g2","text":"Say hand","keywords":["hand"],"examplePhrase":"Hand"},{"id":"g3","text":"Say eyes","keywords":["eye","eyes"],"examplePhrase":"Eyes"}]', '[{"id":"p1","phrase":"This is my head.","translation":"Esta es mi cabeza."},{"id":"p2","phrase":"This is my hand.","translation":"Esta es mi mano."},{"id":"p3","phrase":"These are my eyes.","translation":"Estos son mis ojos."}]', true, true, now()),
  (1, 'Food Words', 'Say words for food and drink.', 'You look at food on a table.', 'PRE-A1', 'cooking', 1, 'Say water, bread, milk and apple.', 'Friend', 'New Speaker', 'Look! Water and bread.', '[{"id":"g1","text":"Say water","keywords":["water"],"examplePhrase":"Water"},{"id":"g2","text":"Say bread","keywords":["bread"],"examplePhrase":"Bread"},{"id":"g3","text":"Say milk or apple","keywords":["milk","apple"],"examplePhrase":"Milk"}]', '[{"id":"p1","phrase":"Water, please.","translation":"Agua, por favor."},{"id":"p2","phrase":"Bread, please.","translation":"Pan, por favor."},{"id":"p3","phrase":"I like milk.","translation":"Me gusta la leche."}]', true, true, now()),
  (1, 'Ordering a Drink', 'Ask for one simple drink.', 'You are in a small cafe.', 'PRE-A1', 'travel', 1, 'Ask for water or tea with one word.', 'Waiter', 'Customer', 'Hello. What do you want?', '[{"id":"g1","text":"Ask for water","keywords":["water"],"examplePhrase":"Water"},{"id":"g2","text":"Say please","keywords":["please"],"examplePhrase":"Water, please"},{"id":"g3","text":"Say thank you","keywords":["thank","thanks"],"examplePhrase":"Thank you"}]', '[{"id":"p1","phrase":"Water, please.","translation":"Agua, por favor."},{"id":"p2","phrase":"Tea, please.","translation":"Té, por favor."},{"id":"p3","phrase":"Thank you.","translation":"Gracias."}]', true, true, now()),
  (1, 'Asking for Help', 'Ask for help with one word.', 'You need help in the street.', 'PRE-A1', 'daily', 1, 'Say help and please.', 'Stranger', 'New Speaker', 'Are you okay?', '[{"id":"g1","text":"Say help","keywords":["help"],"examplePhrase":"Help"},{"id":"g2","text":"Say help me","keywords":["help","me"],"examplePhrase":"Help me"},{"id":"g3","text":"Say thank you","keywords":["thank","thanks"],"examplePhrase":"Thank you"}]', '[{"id":"p1","phrase":"Help!","translation":"¡Ayuda!"},{"id":"p2","phrase":"Help me, please.","translation":"Ayúdame, por favor."},{"id":"p3","phrase":"Thank you.","translation":"Gracias."}]', true, true, now()),
  (1, 'I Don''t Understand', 'Say that you do not understand.', 'Someone speaks too fast for you.', 'PRE-A1', 'daily', 1, 'Say simple phrases to ask for repetition.', 'Teacher', 'Student', 'Do you understand me?', '[{"id":"g1","text":"Say no","keywords":["no"],"examplePhrase":"No"},{"id":"g2","text":"Say I do not understand","keywords":["understand"],"examplePhrase":"I do not understand"},{"id":"g3","text":"Say again, please","keywords":["again"],"examplePhrase":"Again, please"}]', '[{"id":"p1","phrase":"I don''t understand.","translation":"No entiendo."},{"id":"p2","phrase":"Again, please.","translation":"Otra vez, por favor."},{"id":"p3","phrase":"Slowly, please.","translation":"Despacio, por favor."}]', true, true, now()),
  (1, 'Days of the Week', 'Say simple days of the week.', 'You talk about the day of the week.', 'PRE-A1', 'daily', 1, 'Say Monday, Sunday and today.', 'Friend', 'New Speaker', 'What day is it today?', '[{"id":"g1","text":"Say Monday","keywords":["monday"],"examplePhrase":"Monday"},{"id":"g2","text":"Say Sunday","keywords":["sunday"],"examplePhrase":"Sunday"},{"id":"g3","text":"Say today","keywords":["today"],"examplePhrase":"Today"}]', '[{"id":"p1","phrase":"Today is Monday.","translation":"Hoy es lunes."},{"id":"p2","phrase":"Sunday.","translation":"Domingo."},{"id":"p3","phrase":"See you on Monday.","translation":"Nos vemos el lunes."}]', true, true, now()),
  (1, 'Weather Words', 'Say simple words about the weather.', 'You talk about the weather outside.', 'PRE-A1', 'daily', 1, 'Say sun, rain and cold.', 'Friend', 'New Speaker', 'Look outside. Is it cold?', '[{"id":"g1","text":"Say sun","keywords":["sun","sunny"],"examplePhrase":"Sun"},{"id":"g2","text":"Say rain","keywords":["rain","rainy"],"examplePhrase":"Rain"},{"id":"g3","text":"Say cold or hot","keywords":["cold","hot"],"examplePhrase":"Cold"}]', '[{"id":"p1","phrase":"It is sunny.","translation":"Hace sol."},{"id":"p2","phrase":"It is raining.","translation":"Está lloviendo."},{"id":"p3","phrase":"It is cold.","translation":"Hace frío."}]', true, true, now()),
  (1, 'Common Objects', 'Say names of everyday objects.', 'You point to objects in a room.', 'PRE-A1', 'daily', 1, 'Say book, phone and bag.', 'Friend', 'New Speaker', 'What is this? A book?', '[{"id":"g1","text":"Say book","keywords":["book"],"examplePhrase":"Book"},{"id":"g2","text":"Say phone","keywords":["phone"],"examplePhrase":"Phone"},{"id":"g3","text":"Say bag","keywords":["bag"],"examplePhrase":"Bag"}]', '[{"id":"p1","phrase":"This is a book.","translation":"Esto es un libro."},{"id":"p2","phrase":"This is a phone.","translation":"Esto es un teléfono."},{"id":"p3","phrase":"This is a bag.","translation":"Esto es una bolsa."}]', true, true, now()),
  (1, 'Making a Simple Sentence', 'Make your first simple sentence.', 'You show things and introduce yourself.', 'PRE-A1', 'daily', 1, 'Say "this is" and "I am" with one word.', 'Teacher', 'Student', 'This is a pen. And you?', '[{"id":"g1","text":"Say this is","keywords":["this","is"],"examplePhrase":"This is"},{"id":"g2","text":"Say I am","keywords":["am"],"examplePhrase":"I am"},{"id":"g3","text":"Say you are","keywords":["you","are"],"examplePhrase":"You are"}]', '[{"id":"p1","phrase":"This is a book.","translation":"Esto es un libro."},{"id":"p2","phrase":"I am happy.","translation":"Estoy feliz."},{"id":"p3","phrase":"You are my friend.","translation":"Eres mi amigo."}]', true, true, now())
